     // Callback function when a device is discovered\n      Serial.printf("Device found: %s \\n", advertisedDevice.toString().c_str());\n    }\n};\n\nvoid setup() {\n  Serial.begin(115200);\n  Serial.println("Initializing BLE Scanner...");\n\n  BLEDevice::init("");\n  pBLEScan = BLEDevice::getScan(); // Create scan object\n  pBLEScan->setAdvertisedDeviceCallbacks(new MyAdvertisedDeviceCallbacks());\n  pBLEScan->setActiveScan(true); // Active scan (consumes more power but gets more complete information)\n  pBLEScan->setInterval(100);\n  pBLEScan->setWindow(99);\n}\n\nvoid loop() {\n  Serial.println("Starting scan...");\n  // false here means do not keep duplicate device results, true to keep\n  BLEScanResults* foundDevices = pBLEScan->start(scanTime, false);\n  \n  Serial.print("Scan finished, number of devices found: ");\n  Serial.println(foundDevices->getCount());\n  Serial.println("Scan completed, clearing results...");\n  \n  pBLEScan->clearResults();   // Clear cache to release memory\n  delay(2000);\n}\n'})}),"\n",(0,s.jsx)(t.h5,{id:"effect-presentation",children:"Effect Presentation"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Upload the code and open the Serial Monitor; the XIAO ESP32-C5 will scan for Bluetooth devices in the surrounding environment and print the relevant information."}),"\n"]}),"\n",(0,s.jsx)("div",{style:{textAlign:"center"},children:(0,s.jsx)("img",{src:"https://files.seeedstudio.com/wiki/XIAO_ESP32C5/Getting_started/ble_usage_1.png",style:{width:800,height:"auto"}})}),"\n",(0,s.jsx)(t.h4,{id:"ble-serverclient",children:"BLE Server/Client"}),"\n",(0,s.jsxs)(t.p,{children:["In BLE Server mode, create a Service and Characteristic, broadcast its presence, and wait for other devices to connect for reading and writing data.",(0,s.jsx)("br",{}),"\nIn BLE Client mode, the Client scans for a specific Service UUID, initiates a connection after finding the Server, and reads or writes the characteristic values of the Server."]})